import {battleActions,maxHp,maxEnergy,effectiveStats,abilities,abilityCatalog} from './combat.mjs';
import {className,skillTypes,skillIcon,categoryOf,typeIds} from './skillbook.mjs';
import {opponentArt} from './battle-stage.mjs';
import {activeStatuses} from './statuses.mjs';
import {skillInfo,statGuide} from './insight-ui.mjs';
export const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const meter=(name,value,max,kind)=>`<div class="hud-meter ${kind}"><span>${name}</span><div><i style="width:${Math.max(0,Math.min(100,value/max*100))}%"></i></div><b>${value}/${max}</b></div>`;
export function compactHud(s){return `<div class="compact-hud"><button class="portrait-button" data-character aria-label="내 캐릭터 정보"><img src="assets/combat/apprentice.png" alt=""><span>정보</span></button><div class="hud-body"><div class="hud-name"><strong>${esc(s.name)}</strong><span>${s.weapon?className(s):'제자'}${s.journey?' · Lv.'+s.journey.level:''}</span></div>${meter('체력',s.hp,maxHp(s),'hp')}${meter('숨',s.energy,maxEnergy(s),'energy')}</div><div class="hud-step"><small>${s.journey?'CHAPTER '+s.journey.chapter:'PROLOGUE'}</small><b>${s.journey?Math.min(9,(s.journey.route?.used||0)+1)+'/9':'첫 숨'}</b></div></div>`;}
function badges(s,side){return `<div class="turn-statuses">${activeStatuses(s,side).map(a=>`<details><summary>${a.name} ${a.stacks>1?a.stacks+'중첩 · ':''}${a.turns}턴</summary><p>${a.description}</p></details>`).join('')}</div>`;}
export function turnBattleView(s,statSnapshot,pathCombat){
 const b=s.battle,actions=battleActions(s),done=!!b.outcome,enemy=opponentArt(s),outcome={victory:'승리',defeat:'전투 불능',retreat:'후퇴'}[b.outcome];
 const skillButton=a=>`<button class="turn-action type-${a.category||'basic'}" data-battle-action="${a.id}" ${a.disabled?'disabled':''}><span class="action-icon">${skillIcon(a.id==='basic'?'weapon':a.id==='defend'?'guard':a.id==='breathe'?'focus':a.id==='release'?'element':a.id)}</span><strong>${esc(a.name)}</strong><small>${a.reason||[a.cost?'숨 '+a.cost:'숨 소모 없음',a.remaining!==undefined&&a.remaining!==null?a.remaining+'/'+a.uses+'회':'',a.cooldown?'대기 '+a.cooldown+'턴':'',a.free?'턴 소모 없음':''].filter(Boolean).join(' · ')}</small>${!a.category?`<span>${esc(a.description)}</span>`:''}</button>`;
 return `<section class="turn-battle" aria-label="턴제 전투"><div class="turn-heading"><b>${done?outcome:'내 턴 · 행동 선택'}</b><span>${b.round}턴</span></div><div class="enemy-card"><div class="enemy-caption"><strong>${esc(b.enemy.name)}</strong><span>${esc(b.enemy.weapon||'짧은 칼')}</span></div>${meter('체력',b.enemy.hp,b.enemy.maxHp,'hp')}${badges(s,'enemy')}<div class="enemy-illustration"><img src="assets/combat/${enemy}.png" alt="${esc(b.enemy.name)}"></div><div class="enemy-intent">${done?'전투 종료':b.enemy.casting?'주문 준비 중 · '+esc(b.enemy.castName):b.enemy.counterReady?'반격 태세':(b.first==='player'?b.round:b.round+1)%(b.enemy.heavyEvery||3)===0?'강한 공격을 준비합니다':'상대가 다음 움직임을 살핍니다'}${b.enemy.shield?' · 적 보호막 '+b.enemy.shield:''}</div></div>${statSnapshot()}${badges(s,'player')}${pathCombat()}<div class="turn-defense">보호막 <b>${b.playerShield}</b>${b.counter?' · 반격 준비':''}${b.empower?' · 다음 공격 +'+b.empower:''}</div>${done?'':`<div class="basic-actions">${actions.filter(a=>!a.category).map(skillButton).join('')}</div><div class="equipped-actions">${Object.keys(typeIds).map(type=>{const a=actions.find(a=>a.category===type);return `<div class="action-slot type-${type}"><span class="action-type">${skillTypes[type]}</span>${a?skillButton(a):'<div class="action-empty">미장착</div>'}${a?`<button class="skill-detail-link" data-inspect="${a.id}" aria-label="${esc(a.name)} 상세">효과·계수 보기</button>`:''}</div>`;}).join('')}</div>`}<div class="turn-feed" role="log" aria-live="polite">${b.log.slice(-5).map(e=>`<p class="${e.actor}"><small>${e.actor==='player'?esc(s.name):e.actor==='enemy'?esc(b.enemy.name):'전투'}</small>${esc(e.text)}</p>`).join('')}</div><details class="full-turn-log"><summary>전체 전투 기록 (${b.log.length})</summary>${b.log.map(e=>`<p>${e.round}턴 · ${esc(e.text)}</p>`).join('')}</details></section>`;
}
export function skillDialog(s,id){const a=abilityCatalog(s).find(a=>a.id===id);if(!a)return '';const known=abilities(s).some(k=>k.id===id),selected=s.loadout?.includes(id);return `<div class="skill-detail-card type-${a.category}"><div class="detail-icon">${skillIcon(id)}</div><small>${skillTypes[a.category]} · ${known?'습득':'미습득'}${selected?' · 선택 중':''}</small><h2>${esc(a.name)}</h2><p>${esc(a.description)}</p><div class="skill-rules"><span>숨 ${a.cost}</span><span>쿨타임 ${a.cooldown}턴</span>${a.uses?`<span>전투당 ${a.uses}회</span>`:''}${a.readyTurn?`<span>${a.readyTurn}턴부터</span>`:''}${a.free?'<span>턴 소모 없음</span>':''}</div>${skillInfo(s,a)}<p class="muted">${a.ingredients?'합성 · '+a.labels?.join(' + '):'습득 등급 '+a.minLevel}${known?'':' · 성장 보상이나 공방에서 배울 수 있습니다.'}</p></div>`;}
export function characterDialog(s){return `<h2>${esc(s.name)}</h2><p class="character-class">${className(s)} · ${s.element||'아직 정하지 않은 결'}</p><div class="character-portrait"><img src="assets/combat/apprentice.png" alt="내 제자"></div><div class="character-vitals">${meter('체력',s.hp,maxHp(s),'hp')}${meter('숨',s.energy,maxEnergy(s),'energy')}</div>${statGuide(s,true)}`;}
